import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.CBxkvBm_.js";const p=JSON.parse('{"title":"CFD (SU2 & OpenFOAM)","description":"","frontmatter":{},"headers":[],"relativePath":"languages/cfd.md","filePath":"languages/cfd.md"}'),l={name:"languages/cfd.md"};function i(c,e,s,n,r,g){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="cfd-su2-openfoam" tabindex="-1">CFD (SU2 &amp; OpenFOAM) <a class="header-anchor" href="#cfd-su2-openfoam" aria-label="Permalink to &quot;CFD (SU2 &amp; OpenFOAM)&quot;">​</a></h1><p><code>@modelscript/cfd</code> (<code>languages/cfd</code>) provides native WebAssembly GLR parsing, parametric configuration materialization, 3D CAD boundary marker synthesis, aerodynamic flow regime analysis, and cross-domain TGG synchronization for Computational Fluid Dynamics solver configurations.</p><hr><h2 id="supported-extensions-dialects" tabindex="-1">Supported Extensions &amp; Dialects <a class="header-anchor" href="#supported-extensions-dialects" aria-label="Permalink to &quot;Supported Extensions &amp; Dialects&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Extension</th><th style="text-align:left;">Dialect</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>.cfg</code>, <code>.su2</code></td><td style="text-align:left;">SU2 Configuration</td><td style="text-align:left;">Native Stanford University Unstructured (<code>SU2_CFD</code>) key-value &amp; marker configuration</td></tr><tr><td style="text-align:left;"><code>.cfgt</code></td><td style="text-align:left;">Parametric CFD Template</td><td style="text-align:left;">SU2 or OpenFOAM template supporting <code>{{ expr }}</code> parameter expressions</td></tr><tr><td style="text-align:left;"><code>.cfd</code></td><td style="text-align:left;">OpenFOAM / Native CFD</td><td style="text-align:left;">OpenFOAM dictionary syntax (<code>FoamFile</code>, <code>dimensions</code>, <code>internalField</code>, <code>boundaryField</code>) and SU2 directives</td></tr></tbody></table><hr><h2 id="parametric-template-materialization-expr" tabindex="-1">Parametric Template Materialization (<code>{{ expr }}</code>) <a class="header-anchor" href="#parametric-template-materialization-expr" aria-label="Permalink to &quot;Parametric Template Materialization (&lt;code v-pre&gt;{{ expr }}&lt;/code&gt;)&quot;">​</a></h2><p>CFD templates (<code>.cfgt</code>, <code>.cfg</code>, <code>.cfd</code>) can embed mathematical expressions in <code>{{ ... }}</code> blocks bound to SysML v2 or Modelica workspace parameters:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SOLVER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">= RANS</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">KIND_TURB_MODEL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">= SST</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">MACH_NUMBER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">= {{ cruise_speed / sqrt(1.4 * 287.05 * ambient_temp) }}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AOA</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">= {{ angle_of_attack_deg }}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">REYNOLDS_NUMBER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">= {{ rho_air * cruise_speed * chord_length / mu_air }}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">MARKER_HEATFLUX</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">= ( battery_plate, {{ heat_dissipation_watts / plate_area }} )</span></span></code></pre></div><p><code>materializeCfdConfig(templateText, parameters)</code> (<code>languages/cfd/src/materializer.ts</code>) evaluates each expression via <code>evaluateCfdExpression</code>, supporting arithmetic operators (<code>+</code>, <code>-</code>, <code>*</code>, <code>/</code>, <code>^</code>), built-in math functions (<code>sin</code>, <code>cos</code>, <code>tan</code>, <code>sqrt</code>, <code>abs</code>, <code>min</code>, <code>max</code>, <code>log</code>, <code>exp</code>), and constants (<code>PI</code>, <code>E</code>).</p><hr><h2 id="_3d-cad-boundary-condition-synthesis" tabindex="-1">3D CAD Boundary Condition Synthesis <a class="header-anchor" href="#_3d-cad-boundary-condition-synthesis" aria-label="Permalink to &quot;3D CAD Boundary Condition Synthesis&quot;">​</a></h2><p>When a user assigns a fluid or thermal boundary condition to a 3D CAD face in the viewport, <code>synthesizeCfdBoundary</code> and <code>applyBoundaryActionToConfig</code> (<code>languages/cfd/src/boundary-synthesizer.ts</code>) synthesize and merge the appropriate directives for either <strong>SU2</strong> or <strong>OpenFOAM</strong>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Boundary Condition</th><th style="text-align:left;">SU2 Directive (<code>.cfg</code> / <code>.su2</code>)</th><th style="text-align:left;">OpenFOAM <code>boundaryField</code> Entry (<code>.cfd</code>)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Velocity / Total Inlet (<code>inlet</code>)</strong></td><td style="text-align:left;"><code>MARKER_INLET= ( &lt;face&gt;, &lt;T_total&gt;, &lt;P_total&gt;, &lt;nx&gt;, &lt;ny&gt;, &lt;nz&gt; )</code></td><td style="text-align:left;"><code>type fixedValue; value uniform (&lt;vx&gt; &lt;vy&gt; &lt;vz&gt;);</code></td></tr><tr><td style="text-align:left;"><strong>Pressure Outlet (<code>outlet</code>)</strong></td><td style="text-align:left;"><code>MARKER_OUTLET= ( &lt;face&gt;, &lt;back_pressure_Pa&gt; )</code></td><td style="text-align:left;"><code>type fixedValue; value uniform &lt;pressure&gt;;</code></td></tr><tr><td style="text-align:left;"><strong>Adiabatic / Heat-Flux Wall (<code>wall</code>)</strong></td><td style="text-align:left;"><code>MARKER_HEATFLUX= ( &lt;face&gt;, &lt;heat_flux_W_m2&gt; )</code></td><td style="text-align:left;"><code>type noSlip;</code> / <code>type fixedGradient; gradient uniform &lt;q&gt;;</code></td></tr><tr><td style="text-align:left;"><strong>Isothermal Wall (<code>isothermal</code>)</strong></td><td style="text-align:left;"><code>MARKER_ISOTHERMAL= ( &lt;face&gt;, &lt;temp_K&gt; )</code></td><td style="text-align:left;"><code>type fixedValue; value uniform &lt;temp_K&gt;;</code></td></tr><tr><td style="text-align:left;"><strong>Far-Field (<code>farfield</code>)</strong></td><td style="text-align:left;"><code>MARKER_FAR= ( &lt;face&gt; )</code></td><td style="text-align:left;"><code>type freestream;</code></td></tr><tr><td style="text-align:left;"><strong>Symmetry Plane (<code>symmetry</code>)</strong></td><td style="text-align:left;"><code>MARKER_SYM= ( &lt;face&gt; )</code></td><td style="text-align:left;"><code>type symmetryPlane;</code></td></tr></tbody></table><hr><h2 id="aerodynamic-theory-slicing-flow-regime-analysis" tabindex="-1">Aerodynamic Theory Slicing &amp; Flow Regime Analysis <a class="header-anchor" href="#aerodynamic-theory-slicing-flow-regime-analysis" aria-label="Permalink to &quot;Aerodynamic Theory Slicing &amp; Flow Regime Analysis&quot;">​</a></h2><p><code>extractCfdSlicingProperties(text)</code> (<code>languages/cfd/src/language.ts</code>) extracts aerodynamic coefficients directly from the CST:</p><ul><li><strong><code>cd</code></strong>: Drag coefficient (<code>DRAG_COEFF</code>, <code>CD</code>, or <code>C_D</code>, default <code>0.3</code>)</li><li><strong><code>refArea</code></strong>: Reference wetted/frontal area (<code>REF_AREA</code>, default <code>1.0</code> $\\text{m}^2$)</li><li><strong><code>density</code></strong>: Freestream fluid density (<code>FREESTREAM_DENSITY</code> or <code>RHO</code>, default <code>1.225</code> $\\text{kg/m}^3$)</li><li><strong><code>freeStreamVelocity</code></strong>: Freestream velocity (<code>FREESTREAM_VELOCITY</code>, default <code>30.0</code> $\\text{m/s}$)</li></ul><p>These properties feed directly into Modelica 1D aerodynamic drag models ($F_d = \\tfrac{1}{2} \\rho v^2 C_d A_{\\text{ref}}$), SysML v2 performance requirements, and the Multi-Domain Theory Coordinator (<code>CaeContractOracle</code>).</p><hr><h2 id="polyglot-tgg-rules" tabindex="-1">Polyglot TGG Rules <a class="header-anchor" href="#polyglot-tgg-rules" aria-label="Permalink to &quot;Polyglot TGG Rules&quot;">​</a></h2><p><code>@modelscript/cfd</code> registers 6 bidirectional Triple Graph Grammar (TGG) rules in <code>languages/cfd/src/language.ts</code>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Rule Name</th><th style="text-align:left;">Source (<code>cfd</code>)</th><th style="text-align:left;">Target Language</th><th style="text-align:left;">Target Construct</th></tr></thead><tbody><tr><td style="text-align:left;"><code>CfdDragPolarToModelicaParam</code></td><td style="text-align:left;"><code>CfdConfig</code> (<code>cd</code>, <code>refArea</code>)</td><td style="text-align:left;"><code>modelica</code></td><td style="text-align:left;"><code>ComponentClause</code> (<code>parameter Real Cd</code>, <code>A_ref</code>)</td></tr><tr><td style="text-align:left;"><code>CfdDragPolarToSysmlAttribute</code></td><td style="text-align:left;"><code>CfdConfig</code> (<code>cd</code>, <code>refArea</code>)</td><td style="text-align:left;"><code>sysml2</code></td><td style="text-align:left;"><code>AttributeUsage</code></td></tr><tr><td style="text-align:left;"><code>CfdInletToModelicaFluidPort</code></td><td style="text-align:left;"><code>Directive</code> (<code>MARKER_INLET</code>)</td><td style="text-align:left;"><code>modelica</code></td><td style="text-align:left;"><code>ComponentClause</code> (<code>Modelica.Fluid.Interfaces.FluidPort_a</code>)</td></tr><tr><td style="text-align:left;"><code>CfdHeatFluxToModelicaHeatPort</code></td><td style="text-align:left;"><code>Directive</code> (<code>MARKER_HEATFLUX</code>)</td><td style="text-align:left;"><code>modelica</code></td><td style="text-align:left;"><code>ComponentClause</code> (<code>Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a</code>)</td></tr><tr><td style="text-align:left;"><code>CfdMarkerToSysmlPort</code></td><td style="text-align:left;"><code>Directive</code> (<code>MARKER_*</code>)</td><td style="text-align:left;"><code>sysml2</code></td><td style="text-align:left;"><code>PortUsage</code></td></tr><tr><td style="text-align:left;"><code>CfdDirectiveToSysmlConstraint</code></td><td style="text-align:left;"><code>Directive</code> (<code>MACH_NUMBER</code>, <code>REYNOLDS_NUMBER</code>)</td><td style="text-align:left;"><code>sysml2</code></td><td style="text-align:left;"><code>ConstraintUsage</code></td></tr></tbody></table>`,23)])])}const y=t(l,[["render",i]]);export{p as __pageData,y as default};
